using Shop;

public class PriceCalculatorTests
{
    private static Order OrderOf(CustomerType customer) =>
        new(customer, [new OrderLine("A", 100m, 2), new OrderLine("B", 50m, 1)]);

    [Fact]
    public void Regular_customer_pays_the_subtotal() =>
        Assert.Equal(250m, PriceCalculator.Total(OrderOf(CustomerType.Regular)));

    [Fact]
    public void Loyal_customer_gets_five_percent_off() =>
        Assert.Equal(237.50m, PriceCalculator.Total(OrderOf(CustomerType.Loyal)));

    [Fact]
    public void Employee_gets_twenty_percent_off() =>
        Assert.Equal(200m, PriceCalculator.Total(OrderOf(CustomerType.Employee)));

    [Fact]
    public void Every_customer_type_has_a_discount_registered()
    {
        foreach (var type in Enum.GetValues<CustomerType>())
            Assert.True(Discounts.ByCustomerType.ContainsKey(type), $"No discount registered for {type}.");
    }

    [Fact]
    public void Applies_the_discount_registered_for_the_customer_type()
    {
        var discounts = new Dictionary<CustomerType, IDiscount> { [CustomerType.Regular] = new PercentageDiscount(0.10m) };
        Assert.Equal(225m, PriceCalculator.Total(OrderOf(CustomerType.Regular), discounts));
    }

    [Fact]
    public void Throws_when_no_discount_is_registered_for_the_customer_type() =>
        Assert.Throws<InvalidOperationException>(() =>
            PriceCalculator.Total(OrderOf(CustomerType.Loyal), new Dictionary<CustomerType, IDiscount>()));
}

